    def decode_not_authorized_error(self, data: str) -> tuple[Any, ...]:
        """Decodes NotAuthorized() custom error arguments."""
        raw = bytes.fromhex(data.removeprefix("0x"))
        if raw[:4] != bytes.fromhex("ea8e4eb5"):
            raise ValueError("Custom error selector mismatch")
        return _strict_abi_decode([], raw[4:])

