    @staticmethod
    def build_deployment(w3: Web3, bytecode: str, transaction: dict[str, Any], registry: ChecksumAddress) -> dict[str, Any]:
        """Builds deployment with caller-supplied bytecode and typed constructor arguments."""
        if transaction.get("value", 0):
            raise ValueError("Constructor is not payable")
        contract = w3.eth.contract(abi=DIESISNAMEPOLICY_ABI, bytecode=bytecode)
        return contract.constructor(registry).build_transaction(transaction)
